# application.yml  (antes: 88 W88-SISTEMAS-PUNTEO y W77-NUM-MOVTOS VALUE 25)
p071:
  renglones-por-respuesta: 25
  sistemas-punteo: [17, 18, 84, 87, 264, 252, 333, 335, 336,
                    404, 408, 500, 501, 502, 701, 703, 707, 711]

// ---------------------------------------------------------------------------
@ConfigurationProperties("p071")
public record SistemasPunteoProperties(@Max(25) int renglonesPorRespuesta,   // OCCURS 25 del mensaje
                                       Set<Integer> sistemasPunteo) {}

@Component
@RequiredArgsConstructor
class SistemasHabilitados {

    private static final int MAX_SISTEMAS = 50;          // WKS-SISTEMAS-RESIDENTES OCCURS 50
    private final LibControlClient libControl;            // B04SISTEM, CONSISMEN, CONSISDIA
    private final SistemasPunteoProperties props;
    @Value("${p071.csi-host}") private int csiHost;
    private List<SistemaHabilitado> tabla;

    @PostConstruct
    void carga() {
        tabla = libControl.sistemas().stream()            // B04SISTEM FUNCION 02 hasta fin
                .filter(s -> props.sistemasPunteo().contains(s.numero()))
                .flatMap(s -> libControl.mensual(s.numero())
                        .flatMap(m -> libControl.diario(s.numero()).map(d -> new Datos(s, m, d)))
                        .stream())
                .filter(x -> x.sistema().estatus() == 3 && resideAqui(x.mensual()))
                .map(x -> new SistemaHabilitado(x.sistema().numero(), x.diario().fecCon(),
                        x.mensual().modSis(), x.mensual().resCsi()))
                .limit(MAX_SISTEMAS)                       // IF W77-IND-SIS < 51
                .toList();
    }

    /** MODSIS 1: reside solo en su CSI. MODSIS 0: CSI 0 (todos) o el propio nodo. */
    private boolean resideAqui(SistemaMensual m) {
        return (m.modSis() == 1 && m.resCsi() == csiHost)
            || (m.modSis() == 0 && (m.resCsi() == 0 || m.resCsi() == csiHost));
    }
}

@Component
class FiltroMensajeSa2 {

    enum Resultado { PROCESA, RECHAZA, FIN, ERROR }

    Resultado evalua(int statusKey, EncabezadoSa2 sa2) {
        if (statusKey == 99) return Resultado.FIN;                    // MOVE 1 TO W77-FIN
        if (!Set.of(0, 89, 92, 93).contains(statusKey)) return Resultado.ERROR;

        // Fuente: SISTEMA = 151 AND CODSERV = 1 AND SUBCODSERV = 1 OR 2
        // COBOL lo evalúa como (151 AND 1 AND SUB = 1) OR (SUB = 2).
        boolean comoEnFuente = (sa2.sistema() == 151 && sa2.codServ() == 1 && sa2.subCodServ() == 1)
                            || sa2.subCodServ() == 2;
        boolean comoSeQuiso  = sa2.sistema() == 151 && sa2.codServ() == 1
                            && (sa2.subCodServ() == 1 || sa2.subCodServ() == 2);
        if (comoEnFuente != comoSeQuiso) {
            log.warn("Mensaje SA2 aceptado solo por la precedencia del fuente: {}", sa2);
        }
        return comoEnFuente ? Resultado.PROCESA : Resultado.RECHAZA;   // RECHAZA: result 2, long 24
    }
}

@Service
@RequiredArgsConstructor
class ConsultaTotalesService {

    private final SistemasHabilitados sistemas;
    private final TotalesClientClassifier librerias;
    private final SistemasPunteoProperties props;

    RespuestaTotales consulta(SolicitudTotales s) {
        var resp = RespuestaTotales.nueva(s.nivel(), props.renglonesPorRespuesta());
        for (SistemaHabilitado sis : sistemas.posterioresA(s.sistemaContinuacion())) {   // > SISCON
            if (resp.llena()) break;                                      // W77-IND > 25
            ResultadoL011 r = librerias.classify(sis.numero()).totales(s.conFecha(s.fecha()));
            resp.agrega(sis, r);                                           // 030321-RECIBE-RESPLIB-FUN1/2
        }
        if (resp.vacia()) {
            return RespuestaTotales.sinDatos(s.nivel());                   // result 2, error(1) = 1
        }
        return resp;
    }
}

/** 030321-RECIBE-RESPLIB-FUN1. */
void agregaNivel1(SistemaHabilitado sis, ResultadoL011 r) {
    renglonActual().error((int) Math.abs(r.codigo() % 10));   // MOVE S9(11) a PIC 9(01): queda el último dígito
    if (r.codigo() == 0 && r.hayMonedas()) {
        r.monedas().stream()
                .takeWhile(m -> m.moneda() > 0)
                .limit(props.renglonesPorRespuesta())
                .forEach(m -> agrega(sis, m));                      // 030326-MUEVE-TOTALES-FUN1
    } else if (sis.numero() == SISTEMA_SIN_CONTINUACION) {           // 711
        continuacion = Continuacion.ninguna();                      // SISCON, MONCON, CAJCON en cero
    } else {
        continuacion = new Continuacion(sis.numero(), 99, 99);      // 99 marca reintento del sistema
    }
}

/** Cada sistema expone la misma interfaz que su librería L011-Snnn. */
public interface TotalesCiClient {
    ResultadoL011 totales(ParametrosL011 p);    // TOTALESCI IN L011-Snnn
}

@Component
class TotalesClientClassifier implements Classifier<Integer, TotalesCiClient> {

    private final Map<Integer, TotalesCiClient> porSistema;

    TotalesClientClassifier(Map<String, TotalesCiClient> beans) {   // beans "l011-s017", "l011-s018", ...
        this.porSistema = beans.entrySet().stream().collect(Collectors.toUnmodifiableMap(
                e -> Integer.parseInt(e.getKey().substring("l011-s".length())), Map.Entry::getValue));
    }

    @Override
    public TotalesCiClient classify(Integer sistema) {
        // Sistema sin librería: el fuente devuelve 3 (MOVE 3 TO W77-RESULT-L011).
        return porSistema.getOrDefault(sistema, p -> ResultadoL011.error(3));
    }
}

/** WKS-MENSAJE-SAL (1795 bytes) con dos vistas: por sucursal y caja, y por sucursal. */
public sealed interface RespuestaTotales permits RespuestaTotales.PorSucursalCaja, RespuestaTotales.PorSucursal {

    record Renglon(int moneda, int sistema,
                   BigDecimal importeCargos,      // 9(16)V9(02) -> escala 2
                   BigDecimal importeAbonos,      // 9(16)V9(02)
                   int numCargos, int numAbonos,  // 9(06)
                   int error) {}                  // 9(01)

    /** Subservicio 2. */
    record PorSucursalCaja(int sucursal, int caja,
                           int monedaContinuacion, int sistemaContinuacion,
                           @Size(max = 25) List<Renglon> renglones) implements RespuestaTotales {}

    /** Subservicio 1. */
    record PorSucursal(int sucursal,
                       int cajaContinuacion, int monedaContinuacion, int sistemaContinuacion,
                       @Size(max = 25) List<Renglon> renglones) implements RespuestaTotales {}
}

/** 030324-MUEVE-TOTALES-FUN2. */
void agregaNivel2(SistemaHabilitado sis, TotalesMoneda m, long codigo) {
    if (m.moneda() <= 0) return;
    renglones.add(new Renglon(m.moneda(), sis.numero(),
            m.importeCargos(), m.importeAbonos(),       // 9(16)V99 a 9(16)V9(02): misma escala
            aContador6(m.numCargos()),                  // 9(08) a 9(06)
            aContador6(m.numAbonos()),
            (int) Math.abs(codigo % 10)));
    continuacion = new Continuacion(sis.numero(), m.moneda(), cajaSolicitada);
}

/** El MOVE de 9(08) a 9(06) pierde los dos dígitos altos; aquí se falla en lugar de truncar. */
private static int aContador6(long n) {
    if (n > 999_999) throw new ContadorDesbordadoException(n);
    return (int) n;
}

@Component
class RespuestaSa2Mapper {

    private static final int HDR_BANAMEX = 48;   // W77-HDR-BNMX
    private static final int HDR_SA2 = 77;       // W77-HDR-SA2

    MensajeSa2 responde(MensajeSa2 entrada, RespuestaTotales r, int longitudDatos) {
        EncabezadoSa2 e = entrada.sa2();
        var sa2 = e.toBuilder()
                .origen(e.destino()).destino(e.origen())         // intercambio sistema/servicio/subservicio
                .resultIca(2).direccion(2).modo(1)
                .prefijoOrigen(e.prefijoDestino()).prefijoDestino(e.prefijoOrigen())
                .longitud(HDR_BANAMEX + HDR_SA2 + longitudDatos)
                .build();
        var hdr = entrada.hdr().intercambiaCcr()
                .withAplOrg("0")
                .withCcrDes(entrada.hdr().copOrg() > 0 ? entrada.hdr().copOrg() : entrada.hdr().ccrOrg());
        return new MensajeSa2(hdr, sa2, RespuestaTotales.serializa(r));
    }
}
